  // js/cart-page.mjs
  function setupCartPage() {
    const list = document.querySelector("[data-cart-items]");
    const content = document.querySelector("[data-cart-content]");
    const empty = document.querySelector("[data-cart-empty]");
    const template = document.querySelector("#cart-item");
    const total = document.querySelector("[data-cart-total]");
    const quantity = document.querySelector("[data-cart-units]");
    function updateSummary(items) {
      content.hidden = items.length === 0;
      empty.hidden = items.length > 0;
      total.textContent = formatPrice(cartTotal(items));
      quantity.textContent = `${items.reduce((sum, item) => sum + item.quantity, 0)} шт.`;
    }
    function createRow(item) {
      const row = template.content.firstElementChild.cloneNode(true);
      row.dataset.id = item.id;
      const link = row.querySelector("[data-item-link]");
      link.href = item.page;
      link.textContent = item.name;
      row.querySelector("img").src = `images/${item.photo}-320.webp`;
      row.querySelector("[data-item-price]").textContent = `${formatPrice(item.price)} за шт.`;
      row.querySelector("[data-item-subtotal]").textContent = formatPrice(item.price * item.quantity);
      const select = row.querySelector("select");
      select.setAttribute("aria-label", `Количество — ${item.name}`);
      for (let value = 1; value <= MAX_QUANTITY; value += 1) {
        select.options.add(new Option(value, value, false, value === item.quantity));
      }
      row.querySelector("button").setAttribute("aria-label", `Удалить — ${item.name}`);
      return row;
    }
    function renderCart(cart) {
      const items = getCartItems(cart);
      list.replaceChildren(...items.map(createRow));
      updateSummary(items);
    }
    list.addEventListener("change", (event) => {
      const select = event.target.closest("select");
      if (!select) return;
      const row = select.closest("[data-id]");
      const cart = loadCart();
      const id = row.dataset.id;
      if (!cart[id]) {
        renderCart(cart);
        return;
      }
      const next = setQuantity(cart, id, Number(select.value));
      if (!saveCart(next)) {
        select.value = cart[id];
        return;
      }
      const items = getCartItems(next);
      const item = items.find((product) => product.id === id);
      row.querySelector("[data-item-subtotal]").textContent = formatPrice(item.price * item.quantity);
      updateSummary(items);
      announceCart(`Итого: ${formatPrice(cartTotal(items))}.`);
    });
    list.addEventListener("click", (event) => {
      const remove = event.target.closest("button");
      if (!remove) return;
      const row = remove.closest("[data-id]");
      const cart = setQuantity(loadCart(), row.dataset.id, 0);
      if (!saveCart(cart)) return;
      const nextRow = row.nextElementSibling ?? row.previousElementSibling;
      row.remove();
      updateSummary(getCartItems(cart));
      (nextRow?.querySelector("button") ?? empty.querySelector("a")).focus();
      announceCart("Товар удалён из корзины.");
    });
    renderCart(loadCart());
    onCartStorageChange(renderCart);
  }

  // js/catalog.js
  function setupCatalog() {
    const filters = document.querySelector(".catalog-filters__form");
    const productGrid = document.querySelector(".catalog-layout .products-grid");
    const products = [...productGrid.children];
    const params = new URLSearchParams(window.location.search);
    const categoryParams = params.getAll("category");
    const search = params.get("q") ?? "";
    function selectOption(name) {
      const select = filters.elements.namedItem(name);
      const value = params.get(name);
      select.value = [...select.options].some((option) => option.value === value) ? value : "";
      return select.value;
    }
    function readPrice(name) {
      const field = filters.elements.namedItem(name);
      const value = params.get(name);
      const price = Number(value);
      field.value = value?.trim() && Number.isFinite(price) && price >= 0 ? price : "";
      return field.valueAsNumber;
    }
    const type = selectOption("type");
    const sort = selectOption("sort");
    const minimum = readPrice("price-from");
    const maximum = readPrice("price-to");
    const inStock = params.get("in-stock") === "yes";
    filters.elements.namedItem("q").value = search;
    filters.elements.namedItem("in-stock").checked = inStock;
    const selectedCategories = [];
    for (const input of filters.querySelectorAll('[name="category"]')) {
      input.checked = categoryParams.includes(input.value);
      if (input.checked) {
        selectedCategories.push(input.value);
      }
    }
    const query = search.trim().toLocaleLowerCase("ru");
    const getPrice = (card) => Number(card.dataset.price);
    let count2 = 0;
    for (const card of products) {
      const price = getPrice(card);
      const available = card.dataset.inStock === "true";
      const collection = !available && card.dataset.category === "sale" ? "" : card.dataset.category;
      const searchable = [
        card.querySelector(".product-card__title").textContent,
        card.querySelector(".product-card__description").textContent
      ].join(" ").toLocaleLowerCase("ru");
      const matches = (!type || card.dataset.type === type) && (!selectedCategories.length || selectedCategories.includes(collection)) && (!inStock || available) && (Number.isNaN(minimum) || price >= minimum) && (Number.isNaN(maximum) || price <= maximum) && searchable.includes(query);
      card.hidden = !matches;
      count2 += Number(matches);
    }
    if (sort) {
      const direction = sort === "price-desc" ? -1 : 1;
      products.sort((first, second) => direction * (getPrice(first) - getPrice(second)));
      productGrid.append(...products);
    }
    document.querySelector(".catalog-layout__count").textContent = `Найдено товаров: ${count2}`;
    document.querySelector(".catalog-layout__empty").hidden = count2 > 0;
    const disclosure = document.querySelector(".catalog-filters__disclosure");
    const compactLayout = window.matchMedia("(max-width: 950px)");
    disclosure.open = !compactLayout.matches;
    compactLayout.addEventListener("change", (event) => {
      disclosure.open = !event.matches;
    });
    const hasFilters = type || query || selectedCategories.length || inStock || Number.isFinite(minimum) || Number.isFinite(maximum) || sort;
    document.querySelector(".catalog-layout__reset").hidden = !hasFilters;
  }

